import { useEffect, useState } from 'react'
import { useAccount, useBalance } from 'wagmi'
import { useQuery } from '@tanstack/react-query'
import { getAddressInfo, getAddressHistory, getAddressTransactions } from './lib/ethplorer'
import { formatNumber, formatUsd, shortAddr, isAddress } from './lib/format'
import { ConnectWallet } from './components/ConnectWallet'
import { AddressSearch } from './components/AddressSearch'
import { TokenList } from './components/TokenList'
import { TxHistory } from './components/TxHistory'
import { Stat } from './components/Stat'
import personalize from './personalize.json'

const DEFAULT_ADDR = '0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045'

export default function App() {
  const { address: connected, isConnected } = useAccount()
  const [target, setTarget] = useState<string>(DEFAULT_ADDR)

  const [autoLatched, setAutoLatched] = useState(false)
  useEffect(() => {
    if (isConnected && connected && !autoLatched) {
      setTarget(connected)
      setAutoLatched(true)
    }
    if (!isConnected) setAutoLatched(false)
  }, [isConnected, connected, autoLatched])

  const infoQ = useQuery({
    queryKey: ['addrInfo', target],
    queryFn: () => getAddressInfo(target),
    enabled: isAddress(target),
    staleTime: 60_000,
  })

  const txQ = useQuery({
    queryKey: ['addrTx', target],
    queryFn: () => getAddressTransactions(target, 25),
    enabled: isAddress(target),
    staleTime: 60_000,
  })

  const opsQ = useQuery({
    queryKey: ['addrOps', target],
    queryFn: () => getAddressHistory(target, 30),
    enabled: isAddress(target),
    staleTime: 60_000,
  })

  const liveBalance = useBalance({
    address: target as `0x${string}`,
    query: { enabled: isAddress(target), refetchInterval: 15_000 },
  })

  return (
    <div className="min-h-screen relative">
      <div className="absolute inset-x-0 top-0 h-[420px] glow pointer-events-none" />
      <Header onPick={(a) => setTarget(a)} />

      <main className="relative max-w-6xl mx-auto px-5 pb-24">
        <Hero />

        <section className="mt-8">
          <AddressSearch value={target} onSubmit={(a) => setTarget(a)} />
        </section>

        <section className="mt-8">
          <AddressHeader
            address={target}
            loading={infoQ.isLoading}
            live={liveBalance.data ? Number(liveBalance.data.formatted) : undefined}
            info={infoQ.data}
            isOwn={isConnected && connected?.toLowerCase() === target.toLowerCase()}
          />
        </section>

        <section className="mt-6 grid gap-6 lg:grid-cols-5">
          <div className="lg:col-span-3">
            {infoQ.isError ? (
              <ErrorCard title="Couldn't load holdings" message={(infoQ.error as Error)?.message} />
            ) : infoQ.data ? (
              <TokenList info={infoQ.data} />
            ) : (
              <SkeletonCard rows={5} />
            )}
          </div>
          <div className="lg:col-span-2">
            {txQ.isError || opsQ.isError ? (
              <ErrorCard
                title="Couldn't load activity"
                message={((txQ.error || opsQ.error) as Error)?.message}
              />
            ) : (
              <TxHistory
                address={target}
                txs={txQ.data || []}
                ops={opsQ.data || []}
                loading={txQ.isLoading || opsQ.isLoading}
              />
            )}
          </div>
        </section>

        <Features />
      </main>

      <Footer />
    </div>
  )
}

