import { useState } from 'react'
import './index.css'
import { MOCK_PROPOSALS } from './data'
import type { Proposal, CreateProposalForm } from './types'
import { ProposalList } from './components/ProposalList'
import { ProposalDetail } from './components/ProposalDetail'
import { CreateProposal } from './components/CreateProposal'

type View = { page: 'list' } | { page: 'detail'; id: string } | { page: 'create' }

export default function App() {
  const [proposals, setProposals] = useState<Proposal[]>(MOCK_PROPOSALS)
  const [view, setView] = useState<View>({ page: 'list' })

  function handleVote(proposalId: string, support: 0 | 1 | 2, reason: string) {
    setProposals(ps =>
      ps.map(p => {
        if (p.id !== proposalId) return p
        const weight = 500_000
        const newVote = {
          voter: '0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045',
          support,
          weight,
          reason: reason || undefined,
          timestamp: Date.now(),
        }
        return {
          ...p,
          forVotes: support === 1 ? p.forVotes + weight : p.forVotes,
          againstVotes: support === 0 ? p.againstVotes + weight : p.againstVotes,
          abstainVotes: support === 2 ? p.abstainVotes + weight : p.abstainVotes,
          votes: [newVote, ...p.votes],
        }
      })
    )
  }

  function handleCreate(form: CreateProposalForm) {
    const newProposal: Proposal = {
      id: `0x${Math.random().toString(16).slice(2, 8)}`,
      proposalId: Math.max(...proposals.map(p => p.proposalId)) + 1,
      proposer: '0xd8dA6BF26964aF9D7eEd9e03E53415D37aA96045',
      title: form.title,
      description: form.description,
      state: 'pending',
      forVotes: 0,
      againstVotes: 0,
      abstainVotes: 0,
      quorumVotes: 4_000_000,
      startBlock: 19_870_000 + 14400,
      endBlock: 19_870_000 + 14400 + 50400,
      currentBlock: 19_760_000,
      createdAt: Date.now(),
      targets: [form.target],
      values: [form.value],
      signatures: [form.signature],
      calldatas: [form.calldata],
      votes: [],
      tags: [],
    }
    setProposals(ps => [newProposal, ...ps])
    setView({ page: 'list' })
  }

  if (view.page === 'detail') {
    const proposal = proposals.find(p => p.id === view.id)!
    return (
      <ProposalDetail
        proposal={proposal}
        onBack={() => setView({ page: 'list' })}
        onVote={handleVote}
      />
    )
  }

  if (view.page === 'create') {
    return (
      <CreateProposal
        onBack={() => setView({ page: 'list' })}
        onSubmit={handleCreate}
      />
    )
  }

  return (
    <ProposalList
      proposals={proposals}
      onSelect={id => setView({ page: 'detail', id })}
      onCreateNew={() => setView({ page: 'create' })}
    />
  )
}

