import { useEffect, useState } from 'react'
import './index.css'
import { agentEngine } from './agentEngine'
import type { AgentState } from './types'
import { StatusBar } from './components/StatusBar'
import { PositionPanel } from './components/PositionPanel'
import { PnlPanel } from './components/PnlPanel'
import { LogStream } from './components/LogStream'
import { StrategyEditor } from './components/StrategyEditor'
import { KillSwitch } from './components/KillSwitch'

export default function App() {
  const [state, setState] = useState<AgentState | null>(null)
  const [killArmed, setKillArmed] = useState(false)
  const [killReason, setKillReason] = useState<string | null>(null)

  useEffect(() => {
    const unsub = agentEngine.subscribe(s => {
      setState(s)
      const ks = agentEngine.getKillState()
      setKillArmed(ks.armed)
      setKillReason(ks.reason)
    })
    return unsub
  }, [])

  if (!state) return null

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        height: '100svh',
        background: '#0a0c10',
        overflow: 'hidden',
      }}
    >
      {/* Top status bar */}
      <StatusBar state={state} />

      {/* Main grid */}
      <div
        style={{
          flex: 1,
          display: 'grid',
          gridTemplateColumns: '280px 1fr 280px',
          gridTemplateRows: '1fr 1fr',
          gap: 6,
          padding: 6,
          minHeight: 0,
        }}
      >
        {/* Col 1, Row 1: Position */}
        <div style={{ gridColumn: 1, gridRow: 1, minHeight: 0 }}>
          <PositionPanel positions={state.positions} />
        </div>

        {/* Col 1, Row 2: PnL */}
        <div style={{ gridColumn: 1, gridRow: 2, minHeight: 0 }}>
          <PnlPanel history={state.pnlHistory} positions={state.positions} />
        </div>

        {/* Col 2, Row 1+2: Strategy Editor (spans both rows) */}
        <div style={{ gridColumn: 2, gridRow: '1 / 3', minHeight: 0 }}>
          <StrategyEditor
            code={state.strategyCode}
            status={state.status}
            onSave={code => agentEngine.updateStrategy(code)}
          />
        </div>

        {/* Col 3, Row 1+2: Logs + Controls */}
        <div
          style={{
            gridColumn: 3,
            gridRow: '1 / 3',
            display: 'flex',
            flexDirection: 'column',
            gap: 6,
            minHeight: 0,
          }}
        >
          <div style={{ flex: 1, minHeight: 0 }}>
            <LogStream logs={state.logs} />
          </div>
          <div style={{ flexShrink: 0 }}>
            <KillSwitch
              status={state.status}
              killArmed={killArmed}
              killReason={killReason}
              onStart={() => agentEngine.start()}
              onStop={() => agentEngine.stop()}
              onKill={() => agentEngine.killSwitch()}
              onReset={() => agentEngine.resetKill()}
            />
          </div>
        </div>
      </div>

      {/* CRT scanline overlay */}
      <div
        style={{
          position: 'fixed',
