import { connectWallet, getNetworkName } from './lib/contract'
import { globalTree, toHex } from './lib/crypto'
import type { MixerNote, AppTab } from './types'

const TABS: { id: AppTab; label: string; desc: string }[] = [
  { id: 'deposit',  label: 'Deposit',  desc: 'Generate commitment + secret note' },
  { id: 'withdraw', label: 'Withdraw', desc: 'Generate ZK proof + redeem funds' },
  { id: 'verify',   label: 'Verify Note', desc: 'Check note integrity' },
]

export default function App() {
  const [tab, setTab] = useState<AppTab>('deposit')
  const [walletAddress, setWalletAddress] = useState<string | null>(null)
  const [network, setNetwork] = useState('sepolia')
  const [deposits, setDeposits] = useState<MixerNote[]>([])
  const [merkleRoot, setMerkleRoot] = useState('0x' + '0'.repeat(64))
  const [showMerkle, setShowMerkle] = useState(false)

  const refreshRoot = useCallback(async () => {
    const r = await globalTree.getRoot()
    setMerkleRoot(toHex(r))
  }, [])

  useEffect(() => { refreshRoot() }, [deposits.length])

  const handleConnect = async () => {
    try {
      const addr = await connectWallet()
      setWalletAddress(addr)
      const net = await getNetworkName()
      setNetwork(net)
    } catch (e) {
      console.error(e)
    }
  }

  const handleDeposit = (note: MixerNote) => {
    setDeposits(prev => [...prev, note])
    refreshRoot()
  }

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      <Header
        walletAddress={walletAddress}
        network={network}
        merkleRoot={merkleRoot}
        leafCount={deposits.length}
        onConnect={handleConnect}
      />

      <main style={{ flex: 1, maxWidth: 1100, margin: '0 auto', width: '100%', padding: '32px 24px', display: 'flex', gap: 28 }}>
        {/* Left: main panel */}
        <div style={{ flex: 1, minWidth: 0 }}>
          {/* Tab bar */}
          <div style={{ display: 'flex', gap: 4, marginBottom: 24, padding: 4, background: 'var(--bg-secondary)', borderRadius: 10, border: '1px solid var(--border)' }}>
            {TABS.map(t => (
              <button
                key={t.id}
                onClick={() => setTab(t.id)}
                style={{
                  flex: 1, padding: '10px 12px', borderRadius: 7, border: 'none',
                  background: tab === t.id ? 'var(--bg-card)' : 'transparent',
                  color: tab === t.id ? 'var(--text-primary)' : 'var(--text-muted)',
                  fontWeight: tab === t.id ? 700 : 400,
                  fontSize: 13, cursor: 'pointer', fontFamily: 'inherit',
                  boxShadow: tab === t.id ? '0 1px 4px rgba(0,0,0,0.4)' : 'none',
                  transition: 'all 0.15s',
                }}
              >
                {t.label}
              </button>
            ))}
          </div>

          {/* Panel description */}
          <div style={{ marginBottom: 20 }}>
            <h1 style={{ fontSize: 22, fontWeight: 700, letterSpacing: '-0.5px', color: 'var(--text-primary)', marginBottom: 4 }}>
              {TABS.find(t => t.id === tab)?.label}
            </h1>
            <p style={{ fontSize: 13, color: 'var(--text-secondary)' }}>
              {TABS.find(t => t.id === tab)?.desc}
            </p>
          </div>

          {/* Panel content */}
          <div className="card" style={{ padding: 24 }}>
            {tab === 'deposit'  && <DepositPanel walletAddress={walletAddress} network={network} onDeposit={handleDeposit} />}
            {tab === 'withdraw' && <WithdrawPanel walletAddress={walletAddress} network={network} />}
            {tab === 'verify'   && <VerifyPanel />}
          </

