import { useBridgeSimulator } from './hooks/useBridgeSimulator'
import type { Token } from './types'
import styles from './App.module.css'

const BRIDGE_CHAINS = [
  { id: 'ethereum', name: 'Ethereum Mainnet', chainId: 1 },
  { id: 'arbitrum', name: 'Arbitrum One', chainId: 42161 },
  { id: 'optimism', name: 'Optimism', chainId: 10 },
  { id: 'base', name: 'Base', chainId: 8453 },
]

export default function App() {
  const { tx, submit, reset, currentL1Block, currentL2Block } = useBridgeSimulator()
  const pipelineRef = useRef<HTMLDivElement>(null)
  const [sourceChain, setSourceChain] = useState('ethereum')
  const [destChain, setDestChain] = useState('arbitrum')

  const sourceName = BRIDGE_CHAINS.find(c => c.id === sourceChain)?.name ?? sourceChain
  const destName = BRIDGE_CHAINS.find(c => c.id === destChain)?.name ?? destChain

  const handleSubmit = useCallback((amount: string, token: Token, recipient: string) => {
    submit(amount, token, recipient)
  }, [submit])

  useEffect(() => {
    if (tx?.status === 'submitted') {
      pipelineRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
  }, [tx?.status])

  const bridging = tx !== null && tx.status !== 'destination_confirmed'

  return (
    <div className={styles.app}>
      <header className={styles.header}>
        <div className={styles.logoMark}>
          <svg width="28" height="28" viewBox="0 0 28 28" fill="none">
            <rect width="28" height="28" rx="8" fill="#627eea" />
            <path d="M8 20 L14 8 L20 20" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" fill="none" />
            <path d="M10 16 L18 16" stroke="white" strokeWidth="2" strokeLinecap="round" />
          </svg>
          <span className={styles.logoText}>Across</span>
        </div>
        <nav className={styles.nav}>
          <a href="#" className={styles.navLink}>Bridge</a>
          <a href="#" className={styles.navLink}>History</a>
          <a href="#" className={styles.navLink}>Docs</a>
        </nav>
        <button className={styles.connectBtn}>Connect Wallet</button>
      </header>

      <main className={styles.main}>
        <div className={styles.grid}>
          <div className={styles.card} ref={pipelineRef}>
            {!tx ? (
              <>
                <div className={styles.cardHeader}>
                  <h1 className={styles.cardTitle}>Bridge {sourceName} → {destName}</h1>
                  <p className={styles.cardSub}>
                    Fast, secure one-way transfers. Funds arrive in ~12 min via the canonical bridge.
                  </p>
                </div>
                <BridgeForm
                  chains={BRIDGE_CHAINS}
                  sourceChain={sourceChain}
                  destChain={destChain}
                  onSourceChainChange={(id) => {
                    if (id === destChain) setDestChain(sourceChain)
                    setSourceChain(id)
                  }}
                  onDestChainChange={(id) => {
                    if (id === sourceChain) setSourceChain(destChain)
                    setDestChain(id)
                  }}
                  onSubmit={handleSubmit}
                  disabled={bridging}
                />
              </>
            ) : (
              <>
                <div className={styles.cardHeader}>
                  <h1 className={styles.cardTitle}>
                    {tx.status === 'destination_confirmed' ? 'Transfer complete' : 'Bridging…'}
                  </h1>
                  <p className={styles.cardSub}>
                    {tx.status === 'destination_confirmed'
                      ? `${tx.amount} ${tx.token.symbol} has arrived on ${destName}.`
                      : `Transferring ${tx.amount} ${tx.token.symbol} to ${destName}.`}
                  </p>

import { useState, useCallback, useEffect } from 'react'
