// ── Pool state ────────────────────────────────────────────────────────────────
const INITIAL_RESERVE_USDC = 500_000   // 500k USDC
const INITIAL_RESERVE_WETH = 200       // 200 WETH  →  mid price = $2,500/ETH
const FEE_NUMERATOR = 997
const FEE_DENOMINATOR = 1000

interface PoolState {
  reserveUSDC: number
  reserveWETH: number
}

// ── AMM math ──────────────────────────────────────────────────────────────────
function getAmountOut(amountIn: number, reserveIn: number, reserveOut: number): number {
  if (amountIn <= 0 || reserveIn <= 0 || reserveOut <= 0) return 0
  const amountInWithFee = amountIn * FEE_NUMERATOR
  return (amountInWithFee * reserveOut) / (reserveIn * FEE_DENOMINATOR + amountInWithFee)
}

function getMidPrice(pool: PoolState, fromUSDC: boolean): number {
  // Returns how many "out" tokens per 1 "in" token
  return fromUSDC
    ? pool.reserveWETH / pool.reserveUSDC   // WETH per USDC
    : pool.reserveUSDC / pool.reserveWETH   // USDC per WETH
}

function getPriceImpact(amountIn: number, reserveIn: number, reserveOut: number): number {
  if (amountIn <= 0) return 0
  const midPrice = reserveOut / reserveIn
  const amountOut = getAmountOut(amountIn, reserveIn, reserveOut)
  const executionPrice = amountOut / amountIn
  return Math.max(0, ((midPrice - executionPrice) / midPrice) * 100)
}

function getMinimumReceived(amountOut: number, slippagePct: number): number {
  return amountOut * (1 - slippagePct / 100)
}

